import{z as B,x as A,o as n,c as p,q as t,j as i,D as e,d as r,s as l,S as s,b as E}from"./chunks/framework.C8m1ZpeB.js";const P=JSON.parse('{"title":"实物期权估值","description":"","frontmatter":{"title":"实物期权估值","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/real-options-valuation.md","filePath":"econ/real-options-valuation.md","lastUpdated":1791413859000}'),d={name:"econ/real-options-valuation.md"};function C(D,a,c,m,F,h){const o=A("Mermaid");return n(),p("div",null,[a[2]||(a[2]=t('<h1 id="实物期权估值" tabindex="-1">实物期权估值 <a class="header-anchor" href="#实物期权估值" aria-label="Permalink to &quot;实物期权估值&quot;">​</a></h1><div class="epigraph"><p>资本预算把等待、扩张、关停写成期权时，要用或有要求权或决策树把门槛抬到 NPV=0 之上；套一个 Black–Scholes 公式不是估值已经完成。</p><footer>—— Dixit and Pindyck, Investment under Uncertainty, 1994；Myers, Determinants of Corporate Borrowing, Journal of Financial Economics 1977 中的增长期权；对照 McDonald and Siegel, QJE 1986</footer></div><p><a href="/econ/eva-residual-income">上一课</a>把 DCF 与剩余收益收成等价。主干里<a href="/econ/real-options-theory">实物期权</a>已经给出门槛 \\(V^\\ast\\gt I\\)。本课缺口是进阶操作：在 NPV 表上如何把扩张、分阶段、关停、转换写成增量价值，而不把 Dixit–Pindyck 重推一遍，也不把交易所隐含波动当成工厂的输入。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>标准 DCF 把政策当成「现在投或永远不投」。增长期权（Myers 1977 已把企业写成期权组合）、分阶段投资、关停与转产，都是后续决策。静态 NPV 漏掉这些决策的价值，会拒绝「今天 NPV 略负、但买到了明天扩张权」的项目，也会接受「今天 NPV 为正、但锁死了关停灵活性」的项目。缺口是估值加法：灵活性的价值 = 有期权的项目价值 − 承诺路径的 DCF。</p><p><span class="marginnote">数字实例：一个今天 NPV 为 −10 的试点项目，若它买到「两年后可投 500 建全规模厂」的选择权，而这项选择权的期望价值超过 10，项目就该接。静态 DCF 只看见 −10 这个数，把选择权整个漏掉了——这正是「NPV 略负仍可投」的来历。</span></p><p>不可交易的项目没有唯一的无套利价。许可证仍是：能复制则用风险中性；不能则用均衡 \\(r_U\\) 调漂移，或把决策树里的概率改成确定性等价。Brealey–Myers 强调：期权思维先于公式。</p><p><span class="marginnote">分阶段：第一期小额投出，买到第二期是否续投的看涨。这与风险投资后课的 staging 同构，本课站在产业项目，不写 VC 合同条款。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>先画树：节点是可观测的市场或需求，行动是投、等、扩、关。每条承诺路径用上一课口径做 DCF；在决策节点取最大化。连续时间：McDonald–Siegel 阈值；扩张期权像看涨，关停像看跌（残值是执行价）。波动率应来自项目价值 \\(V\\) 的驱动变量（产出价格），不是本公司股票历史波动——股票含杠杆与其他业务。</p><p><span class="marginnote">术语翻译：实物期权里的「波动率」指项目产出价格或项目价值的波动，不是公司股票的历史波动。股票价格里混着杠杆放大与其他业务的噪声，拿它当输入，期权价值和执行门槛会整体算偏——这是实务中最常见的口径错误之一。</span></p><p>与 APV：融资灵活性（延迟发债、补贴到期）也可以是期权，但优先放进债务路径，不要把税盾再写成一个 BS。与 WACC：折现率在期权里随有效杠杆和风险变；决策树用风险中性或确定性等价，比每枝一个 WACC 更不易混。</p>',12)),(n(),i(s,null,{default:e(()=>[l(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20DCF%5B%22%E6%89%BF%E8%AF%BA%E8%B7%AF%E5%BE%84%20DCF%22%5D%20--%3E%20BASE%5B%22%E6%97%A0%E7%81%B5%E6%B4%BB%E6%80%A7%E4%BB%B7%E5%80%BC%22%5D%0A%20%20OPT%5B%22%E7%AD%89%E5%BE%85%20%2F%20%E6%89%A9%E5%BC%A0%20%2F%20%E5%85%B3%E5%81%9C%22%5D%20--%3E%20FLEX%5B%22%E7%81%B5%E6%B4%BB%E6%80%A7%E4%BB%B7%E5%80%BC%22%5D%0A%20%20BASE%20--%3E%20TOT%5B%22%E9%A1%B9%E7%9B%AE%E4%BB%B7%E5%80%BC%22%5D%0A%20%20FLEX%20--%3E%20TOT%0A%20%20BS%5B%22%E5%A5%97%E7%94%A8%20BS%20%E5%85%AC%E5%BC%8F%22%5D%20--%3E%20WARN%5B%22%E5%A4%8D%E5%88%B6%E5%A4%B1%E8%B4%A5%E5%88%99%E4%B8%8D%E6%98%AF%E6%97%A0%E5%A5%97%E5%88%A9%E4%BB%B7%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,"Tirole：不可逆投资加不完全市场，等待有价值，但融资约束会强迫提前执行——实物期权价值被债务积压或现金短缺削掉。估值要声明：灵活性是否真的在经理与债权人的合同里可执行。",-1)),a[4]||(a[4]=E("h2",{id:"机制",tabindex:"-1"},[r("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=E("p",null,"机制仍是信息的机会成本：现在执行放弃保险。进阶课要补的是叠加。扩张期权的标的是后续项目的 \\(V\\)，而 \\(V\\) 本身可能已含更下一层期权，容易重复计算终值增长。纪律：终值用竞争均衡 ROIC，增长期权只放在树的决策节点，不在 Gordon 的 \\(g\\) 里再加一次。",-1)),(n(),i(s,null,{default:e(()=>[l(o,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20T0%5B%22%E7%AC%AC%200%20%E6%9C%9F%EF%BC%9A%E5%B0%8F%E9%A2%9D%E8%AF%95%E7%82%B9%E6%8A%95%E8%B5%84%22%5D%20--%3E%20M%5B%22%E7%AC%AC%201%20%E6%9C%9F%E8%A7%82%E5%AF%9F%E7%9C%9F%E5%AE%9E%E9%9C%80%E6%B1%82%22%5D%0A%20%20M%20--%3E%20HI%5B%22%E9%9C%80%E6%B1%82%E8%BE%BE%E6%A0%87%EF%BC%9A%E7%BB%AD%E6%8A%95%E4%BA%8C%E6%9C%9F%22%5D%0A%20%20M%20--%3E%20LO%5B%22%E9%9C%80%E6%B1%82%E4%B8%8D%E8%BE%BE%E6%A0%87%EF%BC%9A%E6%AD%A2%E6%8D%9F%E6%94%BE%E5%BC%83%22%5D%0A%20%20HI%20--%3E%20FULL%5B%22%E8%BF%9B%E5%85%A5%E5%85%A8%E8%A7%84%E6%A8%A1%E8%BF%90%E8%90%A5%22%5D%0A%20%20LO%20--%3E%20RES%5B%22%E5%8F%AA%E6%8D%9F%E5%A4%B1%E9%A6%96%E6%9C%9F%E5%B0%8F%E9%A2%9D%E6%8A%95%E5%85%A5%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=t('<p><span class="marginnote">常见误区：容易把「加增长期权」与「调高终值增长率 \\(g\\)」同时做——两次算的是同一份乐观。纪律是分账：终值按竞争均衡的 ROIC 走，期权价值只挂在决策节点上。同一份灵活性只能收一次钱，收两次就是把估值抬到空中。</span></p><p>债务与期权：股权是资产的看涨，债权人持有安全债减空头看跌（Merton）。项目层面的关停期权若由股东执行，可能损害债（资产替代或提前清算纠纷）。APV 副作用与实物期权会打架；资本预算须标明为谁估值。</p><h3 id="不是把-npv-调过关的第三套-irr" tabindex="-1">不是把 NPV 调过关的第三套 IRR <a class="header-anchor" href="#不是把-npv-调过关的第三套-irr" aria-label="Permalink to &quot;不是把 NPV 调过关的第三套 IRR&quot;">​</a></h3><p>给负 NPV 项目标一个巨大的「战略期权」却不写执行政策、波动与成本，等于取消接受规则。实物期权估值必须能指出：何种价格或需求下执行、放弃的是什么。</p><p><span class="marginnote">复制：产出可对冲（商品、货币）时，期权部分可用衍生品课的技术；需求不可交易时，回到 CAPM 调整的漂移。本栏不进入限价簿上的期权做市。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要重写主干实物期权课的 \\(V^\\ast\\) 推导。本课只补估值加法与和 DCF/终值的边界。下一课租赁：租赁是放弃残值与灵活性的合同，本身像卖出一份资产期权。</p><p>后课默认：灵活性价值 = 有决策的价值 − 承诺 DCF；波动来自项目驱动变量；不与终值 \\(g\\) 重复计算。复制不存在则不是无套利价格。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>灵活性是对承诺路径 DCF 的增量；门槛仍高于 NPV=0。</li><li>决策树或或有要求权；不要用公司股价波动套 BS 交差。</li><li>增长期权不要与 Gordon 终值加两次。</li><li>出处：Dixit and Pindyck 1994；Myers, <em>JFE</em> 1977；McDonald and Siegel, <em>QJE</em> 1986；Brealey, Myers and Allen。</li></ul>',10))])}const V=B(d,[["render",C]]);export{P as __pageData,V as default};
